Example 3. Top module accu. RTL:
// ---- file: Prob001_accu.sv ----
module accu(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output valid_out,
    output [9:0] data_out
);

reg [1:0] counter;
reg [9:0] sum;
reg [9:0] data_out_reg;
reg valid_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        counter <= 2'b00;
        sum <= 10'b0;
        data_out_reg <= 10'b0;
        valid_out_reg <= 1'b0;
    end else begin
        if (valid_in) begin
            if (counter == 2'b11) begin
                counter <= 2'b00;
                sum <= 10'b0;
                data_out_reg <= sum;
                valid_out_reg <= 1'b1;
            end else begin
                sum <= sum + data_in;
                counter <= counter + 1'b1;
                valid_out_reg <= 1'b0;
            end
        end else begin
            valid_out_reg <= 1'b0;
        end
    end
end

always @(posedge clk) begin
    data_out <= data_out_reg;
    valid_out <= valid_out_reg;
end

endmodule
Correct answer: no. vlog reports at least one error. The first error: ** Error: rtl/Prob001_accu.sv(40): (vlog-2110) Illegal reference to net "data_out".

state.rtl:
// ---- file: metrex_06036.v ----
module batpos(
    clk,
    up,
    down,
    reset,
    speed,
    value
    );

    input clk;
    input up, down;             // signal for counting up/down
    input [4:0] speed;          // # of px to increment bats by
    input reset;
    output reg [10:0] value;    // max value is 1024 (px), 11 bits wide

    // initialize bat position to the middle of the screen
    initial begin
        value <= 512;
    end

    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            // go back to the middle
            value <= 512;
        end
        else begin
            if (up) begin
                // prevent bat from going beyond upper bound of the screen
                if ((value - speed) > 0) begin
                    // move bat up the screen
                    value <= value - speed;
                end
            end
            else if (down) begin
                // prevent bat from going beyond lower bound of the screen
                if ((value + speed) < 1024) begin
                    // move bat down the screen
                    value <= value + speed;
                end
            end
        end
    end

endmodule

