  logic wrsize;
  logic wrspeed;
  logic [3:0] wrtrigcfg;
  logic [3:0] wrtrigmask;
  logic [3:0] wrtrigval;
  logic [31:0] _rnd;
  always #(CLK_HALF) clock = ~clock;
  decoder dut (
    .arm_adv(arm_adv),
    .arm_basic(arm_basic),
    .clock(clock),
    .execute(execute),
    .finish_now(finish_now),
    .opcode(opcode),
    .resetCmd(resetCmd),
    .wrFlags(wrFlags),
    .wrTrigChain(wrTrigChain),
    .wrTrigSelect(wrTrigSelect),
    .wrsize(wrsize),
    .wrspeed(wrspeed),
    .wrtrigcfg(wrtrigcfg),
    .wrtrigmask(wrtrigmask),
    .wrtrigval(wrtrigval)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    execute = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    opcode = _rnd[7:0];
  endtask
