state.tb_power:
`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
// Power testbench written by the JEV_RTL harness, in the style of the REvolution
// tb_pt templates: seed 32'hC0DE0042, 8 reset cycles, 16 warm-up cycles, 4000 measured
// cycles, a new random value on each data input in every cycle.
module tb_power_decoder;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic arm_adv;
  logic arm_basic;
  logic clock;
  logic execute;
  logic finish_now;
  logic [7:0] opcode;
  logic resetCmd;
  logic wrFlags;
  logic wrTrigChain;
  logic wrTrigSelect;
  logic wrsize;
  logic wrspeed;
  logic [3:0] wrtrigcfg;
  logic [3:0] wrtrigmask;
  logic [3:0] wrtrigval;
  logic [31:0] _rnd;
  always #(CLK_HALF) clock = ~clock;
  decoder dut (
    .arm_adv(arm_adv),
    .arm_basic(arm_basic),
    .clock(clock),
    .execute(execute),
    .finish_now(finish_now),
    .opcode(opcode),
    .resetCmd(resetCmd),
    .wrFlags(wrFlags),
    .wrTrigChain(wrTrigChain),
    .wrTrigSelect(wrTrigSelect),
    .wrsize(wrsize),
    .wrspeed(wrspeed),
    .wrtrigcfg(wrtrigcfg),
    .wrtrigmask(wrtrigmask),
    .wrtrigval(wrtrigval)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    execute = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    opcode = _rnd[7:0];
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    clock = 1'b0;
    execute = '0;
    opcode = '0;
    repeat (RESET_CYCLES) @(negedge clock);
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge clock); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_power_decoder);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge clock); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_power_decoder TIMEOUT"); $finish; end
endmodule

