                counter <= 2'b00;
                sum <= 10'b0;
                data_out_reg <= sum;
                valid_out_reg <= 1'b1;
            end else begin
                sum <= sum + data_in;
                counter <= counter + 1'b1;
                valid_out_reg <= 1'b0;
            end
        end else begin
            valid_out_reg <= 1'b0;
        end
    end
end

