`endif
// Power testbench written by the JEV_RTL harness, in the style of the REvolution
// tb_pt templates: seed 32'hC0DE0042, 8 reset cycles, 16 warm-up cycles, 4000 measured
// cycles, a new random value on each data input in every cycle.
module tb_power_cf_vdma;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic [63:0] debug_data;
  logic [7:0] debug_trigger;
  logic hdmi_fs_toggle;
  logic [8:0] hdmi_raddr_g;
  logic [7:0] vdma_be;
  logic vdma_be_error;
  logic vdma_clk;
  logic [63:0] vdma_data;
  logic vdma_fs;
  logic vdma_fs_ret;
  logic vdma_fs_ret_toggle;
  logic [8:0] vdma_fs_waddr;
  logic vdma_last;
  logic vdma_ovf;
  logic vdma_ready;
  logic vdma_tpm_oos;
  logic vdma_unf;
  logic vdma_valid;
  logic [8:0] vdma_waddr;
  logic [47:0] vdma_wdata;
  logic vdma_wr;
  logic [63:0] _rnd;
  always #(CLK_HALF) vdma_clk = ~vdma_clk;
  cf_vdma dut (
    .debug_data(debug_data),
    .debug_trigger(debug_trigger),
    .hdmi_fs_toggle(hdmi_fs_toggle),
    .hdmi_raddr_g(hdmi_raddr_g),
    .vdma_be(vdma_be),
    .vdma_be_error(vdma_be_error),
    .vdma_clk(vdma_clk),
    .vdma_data(vdma_data),
    .vdma_fs(vdma_fs),
    .vdma_fs_ret(vdma_fs_ret),
    .vdma_fs_ret_toggle(vdma_fs_ret_toggle),
    .vdma_fs_waddr(vdma_fs_waddr),
    .vdma_last(vdma_last),
    .vdma_ovf(vdma_ovf),
    .vdma_ready(vdma_ready),
    .vdma_tpm_oos(vdma_tpm_oos),
    .vdma_unf(vdma_unf),
    .vdma_valid(vdma_valid),
    .vdma_waddr(vdma_waddr),
    .vdma_wdata(vdma_wdata),
    .vdma_wr(vdma_wr)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    hdmi_fs_toggle = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    hdmi_raddr_g = _rnd[8:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    vdma_be = _rnd[7:0];
    _rnd = '0;
    for (int _i = 0; _i < 2; _i++) _rnd = (_rnd << 32) | $urandom();
    vdma_data = _rnd[63:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    vdma_fs_ret = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    vdma_last = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    vdma_valid = _rnd[0];
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    vdma_clk = 1'b0;
    hdmi_fs_toggle = '0;
    hdmi_raddr_g = '0;
    vdma_be = '0;
    vdma_data = '0;
    vdma_fs_ret = '0;
    vdma_last = '0;
    vdma_valid = '0;
    repeat (RESET_CYCLES) @(negedge vdma_clk);
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge vdma_clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_power_cf_vdma);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge vdma_clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_power_cf_vdma TIMEOUT"); $finish; end
endmodule

state.examples:
Three solved examples: three other designs, each with the exact reachable clock frequency, 1 / (clock period - worst slack), after synthesis with the flow in `flow` at the clock in `clock`. The question is about the design in `rtl`, not about these examples.

Example 1. Top module verified_div_16bit. RTL:
// ---- file: verified_div_16bit.v ----
module verified_div_16bit(
    input wire [15:0] A,
    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

reg [15:0] a_reg;
reg [15:0] b_reg;
reg [31:0] tmp_a;
reg [31:0] tmp_b;
integer i;

always@(*) begin
    a_reg = A;
    b_reg = B;
end

always@(*) begin
    begin
        tmp_a = {16'b0, a_reg};
        tmp_b = {b_reg, 16'b0};
        for(i = 0;i < 16;i = i+1) begin
            tmp_a = tmp_a << 1;
            if (tmp_a >= tmp_b) begin
                tmp_a = tmp_a - tmp_b + 1;
            end
            else begin
                tmp_a = tmp_a;
            end
        end
    end
end

assign odd = tmp_a[31:16];
assign result = tmp_a[15:0];

endmodule
Result: reachable clock frequency 612 MHz. Level: Below 1 GHz.

Example 2. Top module RefModule. RTL:
// ---- file: Prob084_ece241_2013_q12.sv ----

module RefModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  reg [7:0] q;
  always @(posedge clk) begin
    if (enable)
      q <= {q[6:0], S};
  end

  assign Z = q[ {A, B, C} ];

endmodule
Result: reachable clock frequency 2,137 MHz. Level: 2 GHz to 3 GHz.

Example 3. Top module dffl_18. RTL:
// ---- file: metrex_05095.v ----

module dffl_18 (
	clk,
	ld,
	rst,
	d,
	q
);
	// synthesis attribute keep_hierarchy dffl_18 "true";
	input clk;
	input ld;
	input rst;
	input [17:0] d;
	output [17:0] q;
	reg [17:0] q;

	always @(posedge clk) begin
		if (rst == 1'b0) begin
			q <= 18'b0;
		end else if (ld == 1'b1) begin
			q <= d;
		end
	end
endmodule
Result: reachable clock frequency 3,572 MHz. Level: 3 GHz to 4 GHz.

