  reg             vdma_tpm_oos = 'd0;
  reg     [ 4:0]  vdma_be_count = 'd0;
  reg             vdma_be_error = 'd0;
  reg     [ 8:0]  vdma_raddr_g_m1 = 'd0;
  reg     [ 8:0]  vdma_raddr_g_m2 = 'd0;
  reg     [ 8:0]  vdma_raddr = 'd0;
  reg     [ 8:0]  vdma_addr_diff = 'd0;
  reg             vdma_ready = 'd0;
  reg             vdma_almost_full = 'd0;
  reg             vdma_almost_empty = 'd0;
  reg     [ 4:0]  vdma_ovf_count = 'd0;
  reg             vdma_ovf = 'd0;
  reg     [ 4:0]  vdma_unf_count = 'd0;
  reg             vdma_unf = 'd0;

  wire    [47:0]  vdma_tpm_data_s;
  wire            vdma_tpm_mismatch_s;
  wire            vdma_be_error_s;
  wire    [ 9:0]  vdma_addr_diff_s;
  wire            vdma_ovf_s;
  wire            vdma_unf_s;

  function [8:0] g2b;
    input [8:0] g;
    reg   [8:0] b;
    begin
      b[8] = g[8];
      b[7] = b[8] ^ g[7];
      b[6] = b[7] ^ g[6];
      b[5] = b[6] ^ g[5];
      b[4] = b[5] ^ g[4];
      b[3] = b[4] ^ g[3];
      b[2] = b[3] ^ g[2];
      b[1] = b[2] ^ g[1];
      b[0] = b[1] ^ g[0];
      g2b = b;
    end
  endfunction

  assign debug_data[63:61] = 'd0;
  assign debug_data[60:60] = vdma_tpm_oos;
  assign debug_data[59:59] = vdma_tpm_mismatch_s;
  assign debug_data[58:58] = vdma_wr;
  assign debug_data[57:57] = vdma_ovf_s;
  assign debug_data[56:56] = vdma_unf_s;
  assign debug_data[55:55] = vdma_almost_full;
  assign debug_data[54:54] = vdma_almost_empty;
  assign debug_data[53:53] = vdma_fs;
  assign debug_data[52:52] = vdma_fs_ret;
  assign debug_data[51:51] = vdma_valid;
  assign debug_data[50:50] = vdma_ready;
  assign debug_data[49:49] = vdma_last;
  assign debug_data[48:48] = vdma_be_error_s;
  assign debug_data[47: 0] = {vdma_data[55:32], vdma_data[23:0]};

  assign debug_trigger[7] = vdma_tpm_mismatch_s;
  assign debug_trigger[6] = vdma_be_error_s;
  assign debug_trigger[5] = vdma_ovf_s;
  assign debug_trigger[4] = vdma_unf_s;
  assign debug_trigger[3] = vdma_fs;
  assign debug_trigger[2] = vdma_fs_ret;
  assign debug_trigger[1] = vdma_be_error;
  assign debug_trigger[0] = vdma_ready;

  always @(posedge vdma_clk) begin
    vdma_fs_toggle_m1 <= hdmi_fs_toggle;
    vdma_fs_toggle_m2 <= vdma_fs_toggle_m1;
    vdma_fs_toggle_m3 <= vdma_fs_toggle_m2;
    vdma_fs <= vdma_fs_toggle_m2 ^ vdma_fs_toggle_m3;
    if (vdma_fs_ret == 1'b1) begin
      vdma_fs_waddr <= vdma_waddr;
      vdma_fs_ret_toggle <= ~vdma_fs_ret_toggle;
    end
  end

  always @(posedge vdma_clk) begin
    vdma_wr <= vdma_valid & vdma_ready;
    if (vdma_wr == 1'b1) begin
      vdma_waddr <= vdma_waddr + 1'b1;
    end
    vdma_wdata <= {vdma_data[55:32], vdma_data[23:0]};
  end

  assign vdma_tpm_data_s = {vdma_tpm_data, 1'b1, vdma_tpm_data, 1'b0};
  assign vdma_tpm_mismatch_s = (vdma_wdata == vdma_tpm_data_s) ? 1'b0 : vdma_wr;
  assign vdma_be_error_s = (vdma_be == 8'hff) ? 1'b0 : (vdma_valid & vdma_ready);

  always @(posedge vdma_clk) begin
    if (vdma_fs_ret == 1'b1) begin
      vdma_tpm_data <= 23'd0;
    end else if (vdma_wr == 1'b1) begin
      vdma_tpm_data <= vdma_tpm_data + 1'b1;
    end
    if (vdma_tpm_mismatch_s == 1'b1) begin
      vdma_tpm_mismatch_count <= 5'h10;
    end else if (vdma_tpm_mismatch_count[4] == 1'b1) begin
      vdma_tpm_mismatch_count <= vdma_tpm_mismatch_count + 1'b1;
    end
    vdma_tpm_oos <= vdma_tpm_mismatch_count[4];
    if (vdma_be_error_s == 1'b1) begin
      vdma_be_count <= 5'h10;
    end else if (vdma_be_count[4] == 1'b1) begin
      vdma_be_count <= vdma_be_count + 1'b1;
    end
    vdma_be_error <= vdma_be_count[4];
  end

  assign vdma_addr_diff_s = {1'b1, vdma_waddr} - vdma_raddr;
  assign vdma_ovf_s = (vdma_addr_diff < 3) ? vdma_almost_full : 1'b0;
  assign vdma_unf_s = (vdma_addr_diff > 509) ? vdma_almost_empty : 1'b0;

  always @(posedge vdma_clk) begin
    vdma_raddr_g_m1 <= hdmi_raddr_g;
    vdma_raddr_g_m2 <= vdma_raddr_g_m1;
    vdma_raddr <= g2b(vdma_raddr_g_m2);
    vdma_addr_diff <= vdma_addr_diff_s[8:0];
    if (vdma_addr_diff >= 500) begin
      vdma_ready <= 1'b0;
    end else if (vdma_addr_diff <= 450) begin
      vdma_ready <= 1'b1;
    end
    vdma_almost_full = (vdma_addr_diff > 509) ? 1'b1 : 1'b0;
    vdma_almost_empty = (vdma_addr_diff < 3) ? 1'b1 : 1'b0;
    if (vdma_ovf_s == 1'b1) begin
      vdma_ovf_count <= 5'h10;
    end else if (vdma_ovf_count[4] == 1'b1) begin
      vdma_ovf_count <= vdma_ovf_count + 1'b1;
    end
    vdma_ovf <= vdma_ovf_count[4];
    if (vdma_unf_s == 1'b1) begin
      vdma_unf_count <= 5'h10;
    end else if (vdma_unf_count[4] == 1'b1) begin
      vdma_unf_count <= vdma_unf_count + 1'b1;
    end
    vdma_unf <= vdma_unf_count[4];
  end

endmodule

state.tb_power:
`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
// Power testbench written by the JEV_RTL harness, in the style of the REvolution
// tb_pt templates: seed 32'hC0DE0042, 8 reset cycles, 16 warm-up cycles, 4000 measured
// cycles, a new random value on each data input in every cycle.
module tb_power_cf_vdma;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic [63:0] debug_data;
  logic [7:0] debug_trigger;
  logic hdmi_fs_toggle;
  logic [8:0] hdmi_raddr_g;
  logic [7:0] vdma_be;
  logic vdma_be_error;
  logic vdma_clk;
  logic [63:0] vdma_data;
  logic vdma_fs;
  logic vdma_fs_ret;
  logic vdma_fs_ret_toggle;
  logic [8:0] vdma_fs_waddr;
  logic vdma_last;
  logic vdma_ovf;
  logic vdma_ready;
  logic vdma_tpm_oos;
  logic vdma_unf;
  logic vdma_valid;
  logic [8:0] vdma_waddr;
  logic [47:0] vdma_wdata;
  logic vdma_wr;
  logic [63:0] _rnd;
  always #(CLK_HALF) vdma_clk = ~vdma_clk;
  cf_vdma dut (
    .debug_data(debug_data),
    .debug_trigger(debug_trigger),
    .hdmi_fs_toggle(hdmi_fs_toggle),
    .hdmi_raddr_g(hdmi_raddr_g),
    .vdma_be(vdma_be),
    .vdma_be_error(vdma_be_error),
    .vdma_clk(vdma_clk),
    .vdma_data(vdma_data),
    .vdma_fs(vdma_fs),
    .vdma_fs_ret(vdma_fs_ret),
    .vdma_fs_ret_toggle(vdma_fs_ret_toggle),
    .vdma_fs_waddr(vdma_fs_waddr),
    .vdma_last(vdma_last),
    .vdma_ovf(vdma_ovf),
    .vdma_ready(vdma_ready),
    .vdma_tpm_oos(vdma_tpm_oos),
    .vdma_unf(vdma_unf),
    .vdma_valid(vdma_valid),
    .vdma_waddr(vdma_waddr),
    .vdma_wdata(vdma_wdata),
    .vdma_wr(vdma_wr)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    hdmi_fs_toggle = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    hdmi_raddr_g = _rnd[8:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    vdma_be = _rnd[7:0];
    _rnd = '0;
    for (int _i = 0; _i < 2; _i++) _rnd = (_rnd << 32) | $urandom();
    vdma_data = _rnd[63:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    vdma_fs_ret = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    vdma_last = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    vdma_valid = _rnd[0];
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    vdma_clk = 1'b0;
    hdmi_fs_toggle = '0;
    hdmi_raddr_g = '0;
    vdma_be = '0;
    vdma_data = '0;
    vdma_fs_ret = '0;
    vdma_last = '0;
    vdma_valid = '0;
    repeat (RESET_CYCLES) @(negedge vdma_clk);
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge vdma_clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_power_cf_vdma);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge vdma_clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_power_cf_vdma TIMEOUT"); $finish; end
endmodule

state.examples:
Three solved examples: three other designs, each with the result of the simulator compiler in `tool`. The question is about the design in `rtl`, not about these examples.

Example 1. Top module dffl_18. RTL:
// ---- file: metrex_05095.v ----

module dffl_18 (
	clk,
	ld,
	rst,
	d,
	q
);
	// synthesis attribute keep_hierarchy dffl_18 "true";
	input clk;
	input ld;
	input rst;
	input [17:0] d;
	output [17:0] q;
	reg [17:0] q;

	always @(posedge clk) begin
		if (rst == 1'b0) begin
			q <= 18'b0;
		end else if (ld == 1'b1) begin
			q <= d;
		end
	end
endmodule
Correct answer: yes. vlog reports no error.

Example 2. Top module dffl_18. RTL:
// ---- file: metrex_05095.v ----

module dffl_18 (
