module alu(
    input [3:0] op,
    input [31:0] a,
    input [31:0] b,
    output [31:0] res
);

reg [31:0] result;

always @(*) begin
    case (op)
        4'b0000: result = a + b;
        4'b0001: result = a - b;
        4'b0010: result = a & b;
        4'b0011: result = a | b;
        4'b0100: result = a ^ b;
        4'b0101: result = a << b[4:0];
        4'b0110: result = a >> b[4:0];
        4'b0111: result = a >>> b[4:0];
        4'b1000: result = a < b ? 1 : 0;
        4'b1001: result = a <= b ? 1 : 0;
        4'b1010: result = a > b ? 1 : 0;
        4'b1011: result = a >= b ? 1 : 0;
        4'b1100: result = a == b ? 1 : 0;
        4'b1101: result = a != b ? 1 : 0;
        default: result = 0;
    endcase
end

assign res = result;

endmodule

