// ---- file: metrex_02185.v ----

module stage3_execute(
    input clk_i,
    input rst_i,
    output stall_o,
    input stall_i,
    input [1:0] control_branch_i,
    input control_load_i,
    input control_store_i,
    input [3:0] aluop_i,
    input [31:0] alu_a_i,
    input [31:0] alu_b_i,
    input [31:0] branch_test_val_i,
    input do_wb_i,
    input [4:0] wb_reg_i,
    output reg take_branch_o,
    output [29:0] branch_pc_o,
    output [31:0] alu_o,
    output reg control_load_o,
    output reg control_store_o,
    output reg do_wb_o,
    output reg [4:0] wb_reg_o
);

reg [3:0] aluop;
reg [31:0] alu_a;
reg [31:0] alu_b;
reg [31:0] branch_test_val;
reg [1:0] control_branch;

always @(posedge clk_i) begin
    if (rst_i) begin
        aluop <= 0;
        alu_a <= 0;
        alu_b <= 0;
        branch_test_val <= 0;
        control_branch <= 2'b00;
        control_load_o <= 0;
        control_store_o <= 0;
        do_wb_o <= 0;
        wb_reg_o <= 0;
    end else if (!stall_i) begin
        aluop <= aluop_i;
        alu_a <= alu_a_i;
        alu_b <= alu_b_i;
        branch_test_val <= branch_test_val_i;
        control_branch <= control_branch_i;
        control_load_o <= control_load_i;
        control_store_o <= control_store_i;
        do_wb_o <= do_wb_i;
        wb_reg_o <= wb_reg_i;
    end
end

always @(control_branch or branch_test_val) begin
    case (control_branch)
        2'b00: take_branch_o = 0;
        2'b01: take_branch_o = (branch_test_val != 0);
        2'b10: take_branch_o = (branch_test_val == 0);
        default: take_branch_o = 0;
    endcase
end

assign branch_pc_o = alu_o[29:0];

alu alu0(
    .op(aluop),
    .a(alu_a),
    .b(alu_b),
    .res(alu_o)
);

assign stall_o = stall_i;

endmodule

module alu(
    input [3:0] op,
    input [31:0] a,
    input [31:0] b,
    output [31:0] res
);

reg [31:0] result;

always @(*) begin
    case (op)
        4'b0000: result = a + b;
        4'b0001: result = a - b;
        4'b0010: result = a & b;
        4'b0011: result = a | b;
        4'b0100: result = a ^ b;
        4'b0101: result = a << b[4:0];
        4'b0110: result = a >> b[4:0];
        4'b0111: result = a >>> b[4:0];
        4'b1000: result = a < b ? 1 : 0;
        4'b1001: result = a <= b ? 1 : 0;
        4'b1010: result = a > b ? 1 : 0;
        4'b1011: result = a >= b ? 1 : 0;
        4'b1100: result = a == b ? 1 : 0;
        4'b1101: result = a != b ? 1 : 0;
        default: result = 0;
    endcase
end

assign res = result;

endmodule

