// ---- file: metrex_06042.v ----
module simple_calculator(
    input [1:0] op,
    input [7:0] num1,
    input [7:0] num2,
    output [7:0] result
);

wire [15:0] temp;

assign temp = {op, num1} * {op[0], num2};
assign result = (op == 2'b00) ? num1 + num2 :
                (op == 2'b01) ? num1 - num2 :
                (op == 2'b10) ? temp[15:8] :
                (op == 2'b11) ? (temp[15:8] == 8'h00) ? 8'h00 : temp[15:8] / num2 :
                                8'h00;

endmodule

state.tb_power:
`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
// Power testbench written by the JEV_RTL harness, in the style of the REvolution
// tb_pt templates: seed 32'hC0DE0042, 8 reset cycles, 16 warm-up cycles, 4000 measured
// cycles, a new random value on each data input in every cycle.
module tb_power_simple_calculator;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic _tb_clk;   // paces the inputs, not a port of the design
  logic [7:0] num1;
  logic [7:0] num2;
  logic [1:0] op;
  logic [7:0] result;
  logic [31:0] _rnd;
  always #(CLK_HALF) _tb_clk = ~_tb_clk;
  simple_calculator dut (
    .num1(num1),
    .num2(num2),
    .op(op),
    .result(result)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    num1 = _rnd[7:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    num2 = _rnd[7:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    op = _rnd[1:0];
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    _tb_clk = 1'b0;
    num1 = '0;
    num2 = '0;
    op = '0;
    repeat (RESET_CYCLES) @(negedge _tb_clk);
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge _tb_clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_power_simple_calculator);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge _tb_clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_power_simple_calculator TIMEOUT"); $finish; end
endmodule

