input [35:0] data;
input rdclk;
input rdreq;
input wrclk;
input wrreq;
output [71:0] q;
output rdempty;
output wrfull;
output [8:0] wrusedw;

localparam ADDR_WIDTH = 9;
localparam DATA_WIDTH = 36;
localparam DEPTH = 512;
localparam ADDR_MSB = ADDR_WIDTH - 1;
localparam DATA_MSB = DATA_WIDTH - 1;
localparam Q_WIDTH = 2 * DATA_WIDTH;
localparam Q_MSB = Q_WIDTH - 1;
localparam WRUSEDW_WIDTH = $clog2(DATA_WIDTH + 1);

reg [DATA_MSB:0] mem [DEPTH-1:0];
reg [ADDR_MSB:0] wr_ptr;
reg [ADDR_MSB:0] rd_ptr;
reg [Q_MSB:0] q_reg;
reg [WRUSEDW_WIDTH-1:0] wr_usedw_reg;
reg [WRUSEDW_WIDTH-1:0] wr_usedw_next;
reg wr_en;
reg rd_en;

assign q = q_reg;
assign rdempty = (wr_ptr == rd_ptr) && !wr_en;
assign wrfull = (wr_ptr + 1 == rd_ptr) && rd_en;
assign wrusedw = wr_usedw_reg;

always @(posedge wrclk or negedge aclr) begin
    if (!aclr) begin
        wr_ptr <= 0;
        wr_en <= 0;
        wr_usedw_reg <= 0;
    end else if (wrreq && !wrfull) begin
        mem[wr_ptr] <= data;
        wr_ptr <= wr_ptr + 1;
        wr_usedw_reg <= wr_usedw_next;
        wr_en <= 1;
    end else if (rd_en && (wr_ptr == rd_ptr)) begin
        wr_en <= 0;
    end
end

always @(posedge rdclk or negedge aclr) begin
    if (!aclr) begin
        rd_ptr <= 0;
        rd_en <= 0;
        q_reg <= 0;
    end else if (rdreq && !rdempty) begin
        q_reg <= {mem[rd_ptr], mem[rd_ptr+1]};
        rd_ptr <= rd_ptr + 1;
        rd_en <= 1;
    end else if (wr_en && (wr_ptr == rd_ptr + 1)) begin
        rd_en <= 0;
    end
end

always @(posedge wrclk or negedge aclr) begin
    if (!aclr) begin
        wr_usedw_next <= 0;
    end else if (wrreq && !wrfull) begin
        wr_usedw_next <= {wr_usedw_reg, data[DATA_MSB]};
    end else if (rd_en && (wr_ptr == rd_ptr)) begin
        wr_usedw_next <= 0;
    end
end

endmodule

