`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
module tb_pt_vending_machine;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam real SETTLE_NS = 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic clk;
  logic reset;
  logic condition;
  logic sel;
  logic [1023:0] discountA;
  logic [1023:0] discountB;
  logic [1023:0] discountC;
  logic [1023:0] discountD;
  logic sell_signal;
  logic [1023:0] total_discount;
  logic [2047:0] _rnd;
  always #(CLK_HALF) clk = ~clk;
  vending_machine vending_machine0 (
    .clk(clk),
    .reset(reset),
    .condition(condition),
    .sel(sel),
    .discountA(discountA),
    .discountB(discountB),
    .discountC(discountC),
    .discountD(discountD),
    .sell_signal(sell_signal),
    .total_discount(total_discount)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    condition = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    sel = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 32; _i++) _rnd = (_rnd << 32) | $urandom();
    discountA = _rnd[1023:0];
    _rnd = '0;
    for (int _i = 0; _i < 32; _i++) _rnd = (_rnd << 32) | $urandom();
    discountB = _rnd[1023:0];
    _rnd = '0;
    for (int _i = 0; _i < 32; _i++) _rnd = (_rnd << 32) | $urandom();
    discountC = _rnd[1023:0];
    _rnd = '0;
    for (int _i = 0; _i < 32; _i++) _rnd = (_rnd << 32) | $urandom();
    discountD = _rnd[1023:0];
    reset = (($urandom % 32) == 0) ? 1'b1 : 1'b0;
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    clk = 1'b0;
    condition = '0;
    sel = '0;
    discountA = '0;
    discountB = '0;
    discountC = '0;
    discountD = '0;
    // assert reset
    reset = 1'b1;
    repeat (RESET_CYCLES) @(negedge clk);
    // release reset
    reset = 1'b0;
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_pt_vending_machine);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_pt TIMEOUT"); $finish; end
endmodule

