`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
module tb_pt_cpu_fsm;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam real SETTLE_NS = 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic clk;
  logic rst;
  logic en;
  logic imem_we;
  logic [7:0] imem_addr;
  logic [15:0] imem_wdata;
  logic rf_we;
  logic [1:0] rf_addr;
  logic [7:0] rf_wdata;
  logic [7:0] PC;
  logic halt;
  logic [7:0] dbg_r0;
  logic [7:0] dbg_r1;
  logic [7:0] dbg_r2;
  logic [7:0] dbg_r3;
  logic [2:0] dbg_state;
  logic [131071:0] _rnd;
  always #(CLK_HALF) clk = ~clk;
  mini_cpu mini_cpu0 (
    .clk(clk),
    .rst(rst),
    .en(en),
    .imem_we(imem_we),
    .imem_addr(imem_addr),
    .imem_wdata(imem_wdata),
    .rf_we(rf_we),
    .rf_addr(rf_addr),
    .rf_wdata(rf_wdata),
    .PC(PC),
    .halt(halt),
    .dbg_r0(dbg_r0),
    .dbg_r1(dbg_r1),
    .dbg_r2(dbg_r2),
    .dbg_r3(dbg_r3),
    .dbg_state(dbg_state)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    en = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    imem_we = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    imem_addr = _rnd[7:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    imem_wdata = _rnd[15:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    rf_we = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    rf_addr = _rnd[1:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    rf_wdata = _rnd[7:0];
    rst = (($urandom % 32) == 0) ? 1'b1 : 1'b0;
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    clk = 1'b0;
    en = '0;
    imem_we = '0;
    imem_addr = '0;
    imem_wdata = '0;
    rf_we = '0;
    rf_addr = '0;
    rf_wdata = '0;
    // assert reset
    rst = 1'b1;
    repeat (RESET_CYCLES) @(negedge clk);
    // release reset
    rst = 1'b0;
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_pt_cpu_fsm);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_pt TIMEOUT"); $finish; end
endmodule

state.examples:
Three solved examples: three other designs, each with the exact total cell area after synthesis with the flow in `flow` at the clock in `clock`. The question is about the design in `rtl`, not about these examples.

Example 1. Top module RefModule. RTL:
// ---- file: Prob084_ece241_2013_q12.sv ----

module RefModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  reg [7:0] q;
  always @(posedge clk) begin
    if (enable)
      q <= {q[6:0], S};
  end

  assign Z = q[ {A, B, C} ];

endmodule
Result: total cell area 14.06 um2 = 71.5 GE. Level: Below 100 GE.

Example 2. Top module verified_div_16bit. RTL:
// ---- file: verified_div_16bit.v ----
module verified_div_16bit(
    input wire [15:0] A,
    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

reg [15:0] a_reg;
reg [15:0] b_reg;
reg [31:0] tmp_a;
reg [31:0] tmp_b;
integer i;

always@(*) begin
    a_reg = A;
    b_reg = B;
end

always@(*) begin
    begin
        tmp_a = {16'b0, a_reg};
        tmp_b = {b_reg, 16'b0};
        for(i = 0;i < 16;i = i+1) begin
            tmp_a = tmp_a << 1;
            if (tmp_a >= tmp_b) begin
                tmp_a = tmp_a - tmp_b + 1;
            end
            else begin
                tmp_a = tmp_a;
            end
        end
    end
end

assign odd = tmp_a[31:16];
assign result = tmp_a[15:0];

endmodule
Result: total cell area 260.16 um2 = 1,323.3 GE. Level: 1,000 GE to 10,000 GE.

Example 3. Top module tmu2_dpram. RTL:
