Example 3. Top module accu. RTL:
// ---- file: Prob001_accu.sv ----
module accu(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output valid_out,
    output [9:0] data_out
);

reg [1:0] counter;
reg [9:0] sum;
reg [9:0] data_out_reg;
reg valid_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        counter <= 2'b00;
        sum <= 10'b0;
        data_out_reg <= 10'b0;
        valid_out_reg <= 1'b0;
    end else begin
        if (valid_in) begin
            if (counter == 2'b11) begin
                counter <= 2'b00;
                sum <= 10'b0;
                data_out_reg <= sum;
                valid_out_reg <= 1'b1;
            end else begin
                sum <= sum + data_in;
                counter <= counter + 1'b1;
                valid_out_reg <= 1'b0;
            end
        end else begin
            valid_out_reg <= 1'b0;
        end
    end
end

always @(posedge clk) begin
    data_out <= data_out_reg;
    valid_out <= valid_out_reg;
end

endmodule
