state.tb_power:
`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
module tb_pt_aes;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam real SETTLE_NS = 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic clk;
  logic rst_async_n;
  logic i_start;
  logic [127:0] i_key;
  logic o_done;
  logic [1407:0] o_expanded_key;
  logic [2047:0] _rnd;
  always #(CLK_HALF) clk = ~clk;
  key_expansion_128aes key_expansion_128aes0 (
    .clk(clk),
    .rst_async_n(rst_async_n),
    .i_start(i_start),
    .i_key(i_key),
    .o_done(o_done),
    .o_expanded_key(o_expanded_key)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    i_start = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 4; _i++) _rnd = (_rnd << 32) | $urandom();
    i_key = _rnd[127:0];
    rst_async_n = (($urandom % 32) == 0) ? 1'b0 : 1'b1;
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    clk = 1'b0;
    i_start = '0;
    i_key = '0;
    // assert reset
    rst_async_n = 1'b0;
    repeat (RESET_CYCLES) @(negedge clk);
    // release reset
    rst_async_n = 1'b1;
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_pt_aes);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_pt TIMEOUT"); $finish; end
endmodule

state.examples:
Three solved examples: three other designs, each with the exact reachable clock frequency, 1 / (clock period - worst slack), after synthesis with the flow in `flow` at the clock in `clock`. The question is about the design in `rtl`, not about these examples.

Example 1. Top module verified_div_16bit. RTL:
// ---- file: verified_div_16bit.v ----
module verified_div_16bit(
    input wire [15:0] A,
    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

reg [15:0] a_reg;
reg [15:0] b_reg;
reg [31:0] tmp_a;
reg [31:0] tmp_b;
integer i;

always@(*) begin
    a_reg = A;
    b_reg = B;
end

always@(*) begin
    begin
        tmp_a = {16'b0, a_reg};
        tmp_b = {b_reg, 16'b0};
        for(i = 0;i < 16;i = i+1) begin
            tmp_a = tmp_a << 1;
            if (tmp_a >= tmp_b) begin
                tmp_a = tmp_a - tmp_b + 1;
            end
            else begin
                tmp_a = tmp_a;
            end
        end
    end
end

assign odd = tmp_a[31:16];
assign result = tmp_a[15:0];

endmodule
Result: reachable clock frequency 612 MHz. Level: Below 1 GHz.

Example 2. Top module RefModule. RTL:
// ---- file: Prob084_ece241_2013_q12.sv ----

module RefModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  reg [7:0] q;
  always @(posedge clk) begin
    if (enable)
      q <= {q[6:0], S};
  end

  assign Z = q[ {A, B, C} ];

endmodule
Result: reachable clock frequency 2,137 MHz. Level: 2 GHz to 3 GHz.

Example 3. Top module dffl_18. RTL:
// ---- file: metrex_05095.v ----

module dffl_18 (
	clk,
	ld,
	rst,
	d,
	q
);
	// synthesis attribute keep_hierarchy dffl_18 "true";
	input clk;
	input ld;
	input rst;
	input [17:0] d;
	output [17:0] q;
	reg [17:0] q;

	always @(posedge clk) begin
		if (rst == 1'b0) begin
			q <= 18'b0;
		end else if (ld == 1'b1) begin
			q <= d;
		end
	end
endmodule
Result: reachable clock frequency 3,572 MHz. Level: 3 GHz to 4 GHz.

