`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
module tb_pt_uart;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam real SETTLE_NS = 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic clk;
  logic rst;
  logic [1:0] address;
  logic [31:0] write_data;
  logic we;
  logic rx;
  logic re;
  logic tx;
  logic [7:0] read_data;
  logic [2047:0] _rnd;
  always #(CLK_HALF) clk = ~clk;
  uart_top_design uart_top_design0 (
    .clk(clk),
    .rst(rst),
    .address(address),
    .write_data(write_data),
    .we(we),
    .rx(rx),
    .re(re),
    .tx(tx),
    .read_data(read_data)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    address = _rnd[1:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    write_data = _rnd[31:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    we = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    rx = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    re = _rnd[0];
    rst = (($urandom % 32) == 0) ? 1'b1 : 1'b0;
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    clk = 1'b0;
    address = '0;
    write_data = '0;
    we = '0;
    rx = '0;
    re = '0;
    // assert reset
    rst = 1'b1;
    repeat (RESET_CYCLES) @(negedge clk);
    // release reset
    rst = 1'b0;
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_pt_uart);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_pt TIMEOUT"); $finish; end
endmodule

