`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
module tb_pt_uart;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam real SETTLE_NS = 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic clk;
  logic rst;
  logic [1:0] address;
  logic [31:0] write_data;
  logic we;
  logic rx;
  logic re;
  logic tx;
  logic [7:0] read_data;
  logic [2047:0] _rnd;
  always #(CLK_HALF) clk = ~clk;
  uart_top_design uart_top_design0 (
    .clk(clk),
    .rst(rst),
    .address(address),
    .write_data(write_data),
    .we(we),
    .rx(rx),
    .re(re),
    .tx(tx),
    .read_data(read_data)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    address = _rnd[1:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    write_data = _rnd[31:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    we = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    rx = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    re = _rnd[0];
    rst = (($urandom % 32) == 0) ? 1'b1 : 1'b0;
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    clk = 1'b0;
    address = '0;
    write_data = '0;
    we = '0;
    rx = '0;
    re = '0;
    // assert reset
    rst = 1'b1;
    repeat (RESET_CYCLES) @(negedge clk);
    // release reset
    rst = 1'b0;
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_pt_uart);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_pt TIMEOUT"); $finish; end
endmodule

state.examples:
Three solved examples: three other designs, each with the exact total cell area after synthesis with the flow in `flow` at the clock in `clock`. The question is about the design in `rtl`, not about these examples.

Example 1. Top module RefModule. RTL:
// ---- file: Prob084_ece241_2013_q12.sv ----

module RefModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  reg [7:0] q;
  always @(posedge clk) begin
    if (enable)
      q <= {q[6:0], S};
  end

  assign Z = q[ {A, B, C} ];

endmodule
Result: total cell area 14.06 um2 = 71.5 GE. Level: Below 100 GE.

Example 2. Top module verified_div_16bit. RTL:
// ---- file: verified_div_16bit.v ----
module verified_div_16bit(
    input wire [15:0] A,
    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

reg [15:0] a_reg;
reg [15:0] b_reg;
reg [31:0] tmp_a;
reg [31:0] tmp_b;
integer i;

always@(*) begin
    a_reg = A;
    b_reg = B;
end

always@(*) begin
    begin
        tmp_a = {16'b0, a_reg};
        tmp_b = {b_reg, 16'b0};
        for(i = 0;i < 16;i = i+1) begin
            tmp_a = tmp_a << 1;
            if (tmp_a >= tmp_b) begin
                tmp_a = tmp_a - tmp_b + 1;
            end
            else begin
                tmp_a = tmp_a;
            end
        end
    end
end

assign odd = tmp_a[31:16];
assign result = tmp_a[15:0];

endmodule
Result: total cell area 260.16 um2 = 1,323.3 GE. Level: 1,000 GE to 10,000 GE.

Example 3. Top module tmu2_dpram. RTL:
// ---- file: metrex_11803.v ----

module tmu2_dpram #(
    parameter depth = 11, 
    parameter width = 32
) (
    input sys_clk,

    input [depth-1:0] ra,
    input re,
    output [width-1:0] rd,

    input [depth-1:0] wa,
    input we,
    input [width-1:0] wd
);

reg [width-1:0] ram[0:(1 << depth)-1];

reg [depth-1:0] rar;

always @(posedge sys_clk) begin
    if(re) begin
        rar <= ra;
    end
    if(we) begin
        ram[wa] <= wd;
    end
end

assign rd = ram[rar];

endmodule
Result: total cell area 102,132.74 um2 = 519,474.0 GE. Level: 100,000 GE or more.

