        if (dout_valid_reg) begin
            // Reset dout_valid_reg and cnt after one clock cycle
            dout_valid_reg <= 1'b0;
            cnt <= 4'd0;
        end
    end
end

assign dout_parallel = dout_parallel_reg;
assign dout_valid = dout_valid_reg;

endmodule

