// ---- file: Prob039_serial2parallel.sv ----
module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);

reg [1:0] state; // State machine state (idle, receiving, output)
reg [3:0] cnt; // Counter for the number of bits received
reg [7:0] shift_reg; // Shift register to store incoming serial data

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin // Reset the circuit when rst_n is low
        state <= 2'd0; // Idle state
        cnt <= 4'd0;
        shift_reg <= 8'd0;
        dout_parallel <= 8'd0;
        dout_valid <= 1'd0;
    end else begin
        case (state)
            2'd0: begin // Idle state
                if (din_valid) begin // Transition to receiving state when input data is valid
                    state <= 2'd1;
                    cnt <= 4'd1;
                    shift_reg <= {7'd0, din_serial};
                    dout_valid <= 1'd0;
                end else begin
                    state <= 2'd0; // Stay in idle state if input data is not valid
                    cnt <= 4'd0;
                    shift_reg <= 8'd0;
                    dout_valid <= 1'd0;
                end
            end
            2'd1: begin // Receiving state
                if (cnt < 4'd8 && din_valid) begin // Continue receiving state if input data is valid and 8 bits have not been received
                    cnt <= cnt + 1;
                    shift_reg <= {shift_reg[6:0], din_serial};
                    dout_valid <= 1'd0;
                end else if (cnt == 4'd8) begin // Transition to output state when 8 bits have been received
                    state <= 2'd2;
                    dout_parallel <= shift_reg;
                    dout_valid <= 1'd1;
                end else begin
                    state <= 2'd1; // Stay in receiving state if input data is not valid
                    cnt <= cnt;
                    shift_reg <= shift_reg;
                    dout_valid <= 1'd0;
                end
            end
            2'd2: begin // Output state
                state <= 2'd0; // Transition back to idle state
                cnt <= 4'd0;
                shift_reg <= 8'd0;
                dout_valid <= 1'd0;
            end
        endcase
    end
end

endmodule

state.tb_power:
`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
// Power testbench written by the JEV_RTL harness, in the style of the REvolution
// tb_pt templates: seed 32'hC0DE0042, 8 reset cycles, 16 warm-up cycles, 4000 measured
// cycles, a new random value on each data input in every cycle.
module tb_power_serial2parallel;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic clk;
  logic din_serial;
  logic din_valid;
  logic [7:0] dout_parallel;
  logic dout_valid;
  logic rst_n;
  logic [31:0] _rnd;
  always #(CLK_HALF) clk = ~clk;
  serial2parallel dut (
    .clk(clk),
    .din_serial(din_serial),
    .din_valid(din_valid),
    .dout_parallel(dout_parallel),
    .dout_valid(dout_valid),
    .rst_n(rst_n)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    din_serial = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    din_valid = _rnd[0];
    rst_n = (($urandom % 32) == 0) ? 1'b0 : 1'b1;
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    clk = 1'b0;
    din_serial = '0;
    din_valid = '0;
    rst_n = 1'b0;
    repeat (RESET_CYCLES) @(negedge clk);
    rst_n = 1'b1;
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_power_serial2parallel);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_power_serial2parallel TIMEOUT"); $finish; end
endmodule

