    .aaah(aaah),
    .areset(areset),
    .bump_left(bump_left),
    .bump_right(bump_right),
    .clk(clk),
    .dig(dig),
    .digging(digging),
    .ground(ground),
    .walk_left(walk_left),
    .walk_right(walk_right)
  );
