    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    bump_left = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    bump_right = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    dig = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
