state.tb_power:
`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
// Power testbench written by the JEV_RTL harness, in the style of the REvolution
// tb_pt templates: seed 32'hC0DE0042, 8 reset cycles, 16 warm-up cycles, 4000 measured
// cycles, a new random value on each data input in every cycle.
module tb_power_TopModule;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic aaah;
  logic areset;
  logic bump_left;
  logic bump_right;
  logic clk;
  logic dig;
  logic digging;
  logic ground;
  logic walk_left;
  logic walk_right;
  logic [31:0] _rnd;
  always #(CLK_HALF) clk = ~clk;
  TopModule dut (
    .aaah(aaah),
    .areset(areset),
    .bump_left(bump_left),
    .bump_right(bump_right),
    .clk(clk),
    .dig(dig),
    .digging(digging),
    .ground(ground),
    .walk_left(walk_left),
    .walk_right(walk_right)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    bump_left = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    bump_right = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    dig = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    ground = _rnd[0];
    areset = (($urandom % 32) == 0) ? 1'b1 : 1'b0;
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    clk = 1'b0;
    bump_left = '0;
    bump_right = '0;
    dig = '0;
    ground = '0;
    areset = 1'b1;
    repeat (RESET_CYCLES) @(negedge clk);
    areset = 1'b0;
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_power_TopModule);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_power_TopModule TIMEOUT"); $finish; end
endmodule

