            2'b10: ptr <= (ptr == 7'd0) ? 7'd99 : ptr - 7'd1;  // Left rotate (ptr--)
            default: ptr <= ptr;  // No change
        endcase
    end
end

assign q = rotate_out(storage, ptr);

endmodule

