		end
	end
endmodule
Correct answer: yes. vlog reports no error.

Example 2. Top module dffl_18. RTL:
// ---- file: metrex_05095.v ----

module dffl_18 (
	clk,
	ld,
	rst,
	d,
	q
);
	// synthesis attribute keep_hierarchy dffl_18 "true";
	input clk;
	input ld;
	input rst;
	input [17:0] d;
	output [17:0] q;
	reg [17:0] q;

	always @(posedge clk) begin
		if (rst == 1'b0) begin
			q <= 18'b0;
