			  reg_write   = 1'b1   ;
			  alu_src_imm = 1'b0   ;
			  alu_op      = ALU_ADD;
			  zero_en     = 1'b1   ;
			end

		OP_HALT:
      begin
			  reg_write 	= 1'b0;		
			end

		OP_ADDI :
      begin
			  reg_write 	= 1'b1	 ;
			  alu_src_imm = 1'b1	 ;
			  alu_op      = ALU_ADD;
			  zero_en     = 1'b1	 ;
			end

		OP_SUB :
      begin
			  reg_write 	= 1'b1	 ;
			  alu_src_imm = 1'b0	 ;
			  alu_op      = ALU_SUB;
			  zero_en     = 1'b1	 ;
			end

		OP_CMP:
      begin
			  reg_write 	= 1'b0	 ;
			  alu_src_imm = 1'b0	 ;
			  alu_op      = ALU_SUB;
			  zero_en     = 1'b1	 ;
			end

		OP_BEQ :
      begin
			  reg_write = 1'b0;
			  alu_src_imm = 1'b0	 ;
			  alu_op      = ALU_SUB;
			  branch_en     = 1'b1 ;
			  zero_en     = 1'b0	 ;
			end

		OP_BNE :
      begin
			  reg_write 	= 1'b0	 ;
			  alu_src_imm = 1'b0	 ;
			  alu_op      = ALU_SUB;
			  branch_en   = 1'b1 	 ;
			  zero_en     = 1'b0	 ;
			end

		OP_JMP :
      begin
			  reg_write   = 1'b0;
			  zero_en     = 1'b0;
			end

		default : 
      begin
			  // Do nothing
      end
	endcase

	case(alu_op)

		ALU_ADD : 
      begin
			  alu_result = alu_inA + alu_inB;
			end

		ALU_SUB :
      begin
			  alu_result = alu_inA - alu_inB;
			end

		default : 
      begin
			  // Do nothing.
      end
	endcase
end




always @(*)
begin

	nst = state;
	case (state)

		FETCH:
			nst = DECODE;
		DECODE :
      begin
			  if (opcode == OP_HALT)
				  nst = HALT;
			  else
				  nst = EXEC;
			end
		EXEC:
			nst = WB;
		WB:
			nst = FETCH;
		HALT:
			nst = HALT;

		default:
      begin
        nst = FETCH;
      end	
  endcase
end

endmodule

