// ---- file: metrex_06036.v ----
module batpos(
    clk,
    up,
    down,
    reset,
    speed,
    value
    );

    input clk;
    input up, down;             // signal for counting up/down
    input [4:0] speed;          // # of px to increment bats by
    input reset;
    output reg [10:0] value;    // max value is 1024 (px), 11 bits wide

    // initialize bat position to the middle of the screen
    initial begin
        value <= 512;
    end

    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            // go back to the middle
            value <= 512;
        end
        else begin
            if (up) begin
                // prevent bat from going beyond upper bound of the screen
                if ((value - speed) > 0) begin
                    // move bat up the screen
                    value <= $random;
                end
            end
            else if (down) begin
                // prevent bat from going beyond lower bound of the screen
                if ((value + speed) < 1024) begin
                    // move bat down the screen
                    value <= value + speed;
                end
            end
        end
    end

endmodule

