module cbc_mac_des (
  input        clk,
  input        reset,
  input        valid_i,
  input  [63:0] key_i,
  input  [63:0] data_i,
  output       valid_o,
  output [63:0] mac_o
);

  reg [63:0] iv;
  reg [63:0] key;
  reg [63:0] data;
  reg [63:0] mac;
  reg valid;
  reg [5:0] count;

  assign valid_o = valid;
  assign mac_o   = mac;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      iv     <= 64'h0;
      key    <= 64'h0;
      data   <= 64'h0;
      mac    <= 64'h0;
      valid  <= 1'b0;
      count  <= 6'd0;
    end else begin
      if (valid_i) begin
        case (count)
          6'd0: begin
            iv     <= data_i;
            key    <= key_i;
            data   <= iv ^ key;
            valid  <= 1'b0;
            count  <= count + 1;
          end
          6'd1: begin
            data   <= data_i ^ data;
            valid  <= 1'b0;
            count  <= count + 1;
          end
          6'd2: begin
            data   <= data ^ key;
            mac    <= data;
            valid  <= 1'b1;
            count  <= count + 1;
          end
          6'd3: begin
            iv     <= mac;
            key    <= key_i;
            data   <= iv ^ key;
            valid  <= 1'b0;
            count  <= count + 1;
          end
          6'd4: begin
            data   <= data_i ^ data;
            valid  <= 1'b0;
            count  <= count + 1;
          end
          6'd5: begin
            data   <= data ^ key;
            mac    <= data;
            valid  <= 1'b1;
            count  <= 6'd0;
          end
