// ---- file: adder_16bit.v ----
module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

    // Wires for the carry between lower and upper 8-bit adders
    wire carry;

    // Instantiate the 8-bit adders
    adder_8bit lower_adder (
        .a(a[7:0]),
        .b(b[7:0]),
        .cin(Cin),
        .sum(y[7:0]),
        .cout(carry) // Carry from lower 8 bits
    );

    adder_8bit upper_adder (
        .a(a[15:8]),
        .b(b[15:8]),
        .cin(carry), // Carry from lower 8 bits
        .sum(y[15:8]),
        .cout(Co) // Carry out from the entire 16-bit adder
    );

endmodule

// 8-bit adder module
module adder_8bit (
    input wire [7:0] a,
    input wire [7:0] b,
    input wire cin,
    output wire [7:0] sum,
    output wire cout
);

    wire [6:0] carry;

    // Instantiate the 1-bit full adders
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : full_adder_loop
            if (i == 0) begin
                full_adder fa (
                    .a(a[i]),
                    .b(b[i]),
                    .cin(cin),
                    .sum(sum[i]),
                    .cout(carry[i])
                );
            end else if (i == 7) begin
                full_adder fa (
                    .a(a[i]),
                    .b(b[i]),
                    .cin(carry[i-1]),
                    .sum(sum[i]),
                    .cout(cout)
                );
            end else begin
                full_adder fa (
                    .a(a[i]),
                    .b(b[i]),
                    .cin(carry[i-1]),
                    .sum(sum[i]),
                    .cout(carry[i])
                );
            end
        end
    endgenerate

endmodule

// Full adder module
module full_adder (
    input wire a,
    input wire b,
    input wire cin,
    output wire sum,
    output wire cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (b & cin) | (cin & a);

endmodule

state.tb_power:
`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
// Power testbench written by the JEV_RTL harness, in the style of the REvolution
// tb_pt templates: seed 32'hC0DE0042, 8 reset cycles, 16 warm-up cycles, 4000 measured
// cycles, a new random value on each data input in every cycle.
module tb_power_adder_16bit;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic _tb_clk;   // paces the inputs, not a port of the design
  logic Cin;
  logic Co;
  logic [15:0] a;
  logic [15:0] b;
  logic [15:0] y;
  logic [31:0] _rnd;
  always #(CLK_HALF) _tb_clk = ~_tb_clk;
  adder_16bit dut (
    .Cin(Cin),
    .Co(Co),
    .a(a),
    .b(b),
    .y(y)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    Cin = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    a = _rnd[15:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    b = _rnd[15:0];
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    _tb_clk = 1'b0;
    Cin = '0;
    a = '0;
    b = '0;
    repeat (RESET_CYCLES) @(negedge _tb_clk);
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge _tb_clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_power_adder_16bit);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge _tb_clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_power_adder_16bit TIMEOUT"); $finish; end
endmodule

