                    state <= 2'd1; // Stay in receiving state if input data is not valid
                    cnt <= cnt;
                    shift_reg <= shift_reg;
                    dout_valid <= 1'd0;
                end
            end
            2'd2: begin // Output state
                state <= 2'd0; // Transition back to idle state
