Example 1. Top module verified_div_16bit. RTL:
// ---- file: verified_div_16bit.v ----
module verified_div_16bit(
    input wire [15:0] A,
    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

reg [15:0] a_reg;
reg [15:0] b_reg;
reg [31:0] tmp_a;
reg [31:0] tmp_b;
integer i;

always@(*) begin
    a_reg = A;
    b_reg = B;
end

always@(*) begin
    begin
        tmp_a = {16'b0, a_reg};
        tmp_b = {b_reg, 16'b0};
        for(i = 0;i < 16;i = i+1) begin
            tmp_a = tmp_a << 1;
            if (tmp_a >= tmp_b) begin
                tmp_a = tmp_a - tmp_b + 1;
            end
            else begin
                tmp_a = tmp_a;
            end
        end
    end
end

assign odd = tmp_a[31:16];
assign result = tmp_a[15:0];

endmodule
Result: reachable clock frequency 612 MHz.

Example 2. Top module RefModule. RTL:
// ---- file: Prob084_ece241_2013_q12.sv ----

module RefModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  reg [7:0] q;
  always @(posedge clk) begin
    if (enable)
      q <= {q[6:0], S};
  end

  assign Z = q[ {A, B, C} ];

endmodule
Result: reachable clock frequency 2,137 MHz.

Example 3. Top module dffl_18. RTL:
// ---- file: metrex_05095.v ----

module dffl_18 (
	clk,
	ld,
	rst,
	d,
	q
);
	// synthesis attribute keep_hierarchy dffl_18 "true";
	input clk;
	input ld;
	input rst;
	input [17:0] d;
	output [17:0] q;
	reg [17:0] q;

	always @(posedge clk) begin
		if (rst == 1'b0) begin
			q <= 18'b0;
		end else if (ld == 1'b1) begin
			q <= d;
		end
	end
endmodule
Result: reachable clock frequency 3,572 MHz.

state.rtl_a:
// ---- file: Prob118_history_shift.sv ----
module TopModule (
    input clk,
    input areset,
    input predict_valid,
    input predict_taken,
    input train_mispredicted,
    input train_taken,
    input [31:0] train_history,
    output [31:0] predict_history
);

    reg [31:0] history_buffer;
    reg [4:0] head_ptr;  // Points to current insertion position
    reg [4:0] wrap_count; // Tracks how many times we've wrapped around

    // Circular buffer output generation
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : history_output
            assign predict_history[i] = history_buffer[(head_ptr + i + 1) % 32];
        end
    endgenerate

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            history_buffer <= 32'b0;
            head_ptr <= 5'd31;  // Start at end to match shift behavior
            wrap_count <= 5'd0;
        end
        else if (train_mispredicted) begin
            // Direct load with train_history + train_taken
            history_buffer <= {train_history[30:0], train_taken};
            head_ptr <= 5'd31;
            wrap_count <= 5'd0;
        end
        else if (predict_valid) begin
            // Circular update - overwrite oldest entry when full
            history_buffer[head_ptr] <= predict_taken;
            head_ptr <= (head_ptr == 0) ? 5'd31 : head_ptr - 1;
            if (head_ptr == 0) wrap_count <= wrap_count + 1;
        end
    end

endmodule

state.rtl_b:
// ---- file: Prob118_history_shift.sv ----
module TopModule (
    input clk,
    input areset,
    input predict_valid,
    input predict_taken,
    input train_mispredicted,
    input train_taken,
    input [31:0] train_history,
    output [31:0] predict_history
);

    reg [31:0] history;
    reg [31:0] next_history;
    wire prediction_update = predict_valid & ~train_mispredicted;
    wire [31:0] mispred_update = {train_history[30:0], train_taken};
    wire [31:0] pred_update = {history[30:0], predict_taken};

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            history <= 32'b0;
        end else begin
            history <= next_history;
        end
    end

    always @(*) begin
        casez ({areset, train_mispredicted, prediction_update})
            3'b1??: next_history = 32'b0;
            3'b01?: next_history = mispred_update;
            3'b001: next_history = pred_update;
            default: next_history = history;
        endcase
    end

    assign predict_history = history;

endmodule

state.tb_power:
`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
// Power testbench written by the JEV_RTL harness, in the style of the REvolution
// tb_pt templates: seed 32'hC0DE0042, 8 reset cycles, 16 warm-up cycles, 4000 measured
// cycles, a new random value on each data input in every cycle.
module tb_power_TopModule;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic areset;
  logic clk;
  logic [31:0] predict_history;
  logic predict_taken;
  logic predict_valid;
  logic [31:0] train_history;
  logic train_mispredicted;
  logic train_taken;
  logic [31:0] _rnd;
  always #(CLK_HALF) clk = ~clk;
  TopModule dut (
    .areset(areset),
    .clk(clk),
    .predict_history(predict_history),
    .predict_taken(predict_taken),
    .predict_valid(predict_valid),
    .train_history(train_history),
    .train_mispredicted(train_mispredicted),
    .train_taken(train_taken)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    predict_taken = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    predict_valid = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    train_history = _rnd[31:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    train_mispredicted = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    train_taken = _rnd[0];
    areset = (($urandom % 32) == 0) ? 1'b1 : 1'b0;
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    clk = 1'b0;
    predict_taken = '0;
    predict_valid = '0;
    train_history = '0;
    train_mispredicted = '0;
    train_taken = '0;
    areset = 1'b1;
    repeat (RESET_CYCLES) @(negedge clk);
    areset = 1'b0;
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_power_TopModule);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_power_TopModule TIMEOUT"); $finish; end
endmodule

