// ---- file: metrex_11803.v ----

module tmu2_dpram #(
    parameter depth = 11, 
    parameter width = 32
) (
    input sys_clk,

    input [depth-1:0] ra,
    input re,
    output [width-1:0] rd,

    input [depth-1:0] wa,
