state.examples:
Three solved examples: three other designs, each with the exact total power after synthesis with the flow in `flow` at the clock in `clock`. The question is about the designs in `rtl_a` and `rtl_b`, not about these examples.

Example 1. Top module RefModule. RTL:
// ---- file: Prob084_ece241_2013_q12.sv ----

module RefModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  reg [7:0] q;
  always @(posedge clk) begin
    if (enable)
      q <= {q[6:0], S};
  end

  assign Z = q[ {A, B, C} ];

endmodule
Result: total power 12.48 uW, with a generated power testbench (a new random value on each data input in every cycle, 4,000 measured cycles).

Example 2. Top module cbc_mac_des. RTL:
// ---- file: metrex_19362.v ----
module cbc_mac_des (
  input        clk,
  input        reset,
  input        valid_i,
  input  [63:0] key_i,
  input  [63:0] data_i,
  output       valid_o,
  output [63:0] mac_o
);

  reg [63:0] iv;
  reg [63:0] key;
  reg [63:0] data;
  reg [63:0] mac;
  reg valid;
  reg [5:0] count;

  assign valid_o = valid;
  assign mac_o   = mac;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      iv     <= 64'h0;
      key    <= 64'h0;
      data   <= 64'h0;
      mac    <= 64'h0;
      valid  <= 1'b0;
      count  <= 6'd0;
    end else begin
      if (valid_i) begin
        case (count)
          6'd0: begin
            iv     <= data_i;
            key    <= key_i;
            data   <= iv ^ key;
            valid  <= 1'b0;
            count  <= count + 1;
          end
          6'd1: begin
            data   <= data_i ^ data;
            valid  <= 1'b0;
            count  <= count + 1;
          end
          6'd2: begin
            data   <= data ^ key;
            mac    <= data;
            valid  <= 1'b1;
            count  <= count + 1;
          end
          6'd3: begin
            iv     <= mac;
            key    <= key_i;
            data   <= iv ^ key;
            valid  <= 1'b0;
            count  <= count + 1;
          end
          6'd4: begin
            data   <= data_i ^ data;
            valid  <= 1'b0;
            count  <= count + 1;
          end
          6'd5: begin
            data   <= data ^ key;
            mac    <= data;
            valid  <= 1'b1;
            count  <= 6'd0;
          end
        endcase
      end
    end
  end

endmodule
Result: total power 300.8 uW, with a generated power testbench (a new random value on each data input in every cycle, 4,000 measured cycles).

