    localparam [1:0]
        WALK  = 2'd0,
        DIG   = 2'd1,
        FALL  = 2'd2,
        SPLAT = 2'd3;

    reg [1:0] state, next_state;
    reg       direction, next_direction;  // 0=left, 1=right
    reg [4:0] fall_count, next_fall_count;

    wire bump_any = bump_left | bump_right;
    wire bump_both = bump_left & bump_right;

