state.rtl_a:
// ---- file: Prob155_lemmings4.sv ----
module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // One-hot mode bits
    // walk = 4'b0001, dig = 4'b0010, fall = 4'b0100, splat = 4'b1000
    reg [3:0] mode;
    reg [3:0] mode_next;

    // Direction: 0=left,1=right
    reg direction, direction_next;

    // 5-bit fall timer, counts only during fall
    reg [4:0] fall_timer, fall_timer_next;

    wire bumped = bump_left | bump_right;
    wire both_bumped = bump_left & bump_right;

    // Mode encoding parameters for clarity
    localparam WALK = 4'b0001,
               DIG  = 4'b0010,
               FALL = 4'b0100,
               SPLAT= 4'b1000;

    // Asynchronous reset and state registers
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            mode <= WALK;
            direction <= 1'b0; // start walking left
            fall_timer <= 5'd0;
        end else begin
            mode <= mode_next;
            direction <= direction_next;
            fall_timer <= fall_timer_next;
        end
    end

    // Next-state logic combinational
    always @(*) begin
        // Defaults: hold current state and timer
        mode_next = mode;
        direction_next = direction;
        fall_timer_next = fall_timer;

        casez(mode)
            WALK: begin
                if (!ground) begin
                    // start falling
                    mode_next = FALL;
                    fall_timer_next = 5'd1;
                end else if (dig) begin
                    mode_next = DIG;
                end else begin
                    // change direction if bumped
                    if (both_bumped)
                        direction_next = ~direction;
                    else if (bump_left)
                        direction_next = 1'b1; // walk right
                    else if (bump_right)
                        direction_next = 1'b0; // walk left
                end
            end

            DIG: begin
                if (!ground) begin
                    // ground gone during dig: fall now
                    mode_next = FALL;
                    fall_timer_next = 5'd1;
                end
            end

            FALL: begin
                if (ground) begin
                    // landed
                    if (fall_timer > 5'd20) begin
                        mode_next = SPLAT; // splat after long fall
                        fall_timer_next = 5'd0;
                    end else begin
                        mode_next = WALK;  // resume walking
                        fall_timer_next = 5'd0;
                    end
                end else begin
                    // increment fall timer saturating at 31
                    fall_timer_next = (fall_timer < 5'd31) ? fall_timer + 1 : fall_timer;
                end
            end

            SPLAT: begin
                // remain splatted forever
                mode_next = SPLAT;
                // direction and timer frozen
            end

            default: begin
                // Safety fallback to walking left on unknown state
                mode_next = WALK;
                direction_next = 1'b0;
                fall_timer_next = 5'd0;
            end
        endcase
    end

    // Moore outputs depend solely on current mode and direction
    assign walk_left  = (mode == WALK) && (direction == 1'b0);
    assign walk_right = (mode == WALK) && (direction == 1'b1);
    assign aaah       = (mode == FALL);
    assign digging    = (mode == DIG);

endmodule

state.rtl_b:
// ---- file: Prob155_lemmings4.sv ----
module TopModule (
    input  clk,
    input  areset,       // asynchronous posedge reset
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding: 3 bits (MSB for mode group, lower bits for direction)
    // Modes:
    // 000: WALK_LEFT
    // 001: WALK_RIGHT
    // 010: DIG_LEFT
    // 011: DIG_RIGHT
    // 100: FALL_LEFT
    // 101: FALL_RIGHT
    // 110: SPLAT (direction irrelevant)
    // 111: Unused (treat as SPLAT fallback)

    localparam [2:0]
        WALK_LEFT  = 3'b000,
        WALK_RIGHT = 3'b001,
        DIG_LEFT   = 3'b010,
        DIG_RIGHT  = 3'b011,
        FALL_LEFT  = 3'b100,
        FALL_RIGHT = 3'b101,
        SPLAT      = 3'b110;

    reg [2:0] state, next_state;

    // 5-bit fall timer for timing fall duration (max 31)
    reg [4:0] fall_timer, next_fall_timer;

    // Async reset and state register update
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
            fall_timer <= 5'd0;
        end else begin
            state <= next_state;
            fall_timer <= next_fall_timer;
        end
    end

    // Helper functions
    // Direction bit: LSB of state for all except SPLAT
    wire direction = state[0];

    // State category helpers
    wire is_walk = (state == WALK_LEFT) || (state == WALK_RIGHT);
    wire is_dig  = (state == DIG_LEFT)  || (state == DIG_RIGHT);
    wire is_fall = (state == FALL_LEFT) || (state == FALL_RIGHT);
    wire is_splat = (state == SPLAT);

    // Compute next state and fall_timer
    always @(*) begin
        // Default next state & timer: hold current, no timer increment
        next_state = state;
        next_fall_timer = 5'd0;

        if (is_splat) begin
            // Remain splatted forever
            next_state = SPLAT;
            next_fall_timer = 5'd0;
        end else if (is_fall) begin
            if (ground) begin
                // Landing
                // Check splatter condition: if fall_timer > 20, splat
                if (fall_timer > 5'd20)
                    next_state = SPLAT;
                else
                    // Resume walking preserving direction
                    next_state = (state == FALL_LEFT) ? WALK_LEFT : WALK_RIGHT;

                next_fall_timer = 5'd0;
            end else begin
                // Continue falling, increment timer saturating at 31
                if (fall_timer < 5'd31)
                    next_fall_timer = fall_timer + 1'b1;
                else
                    next_fall_timer = fall_timer;

                next_state = state; // stay falling same direction
            end
        end else if (is_walk) begin
            if (!ground) begin
                // Start falling with current direction
                next_state = (state == WALK_LEFT) ? FALL_LEFT : FALL_RIGHT;
                next_fall_timer = 5'd1; // start count at 1
            end else if (dig) begin
                // Start digging with current direction
                next_state = (state == WALK_LEFT) ? DIG_LEFT : DIG_RIGHT;
                next_fall_timer = 5'd0;
            end else if (bump_left || bump_right) begin
                // Bump switches walking direction
                // Both bumps or either bump causes direction flip or set opposite
                if (bump_left && bump_right) begin
                    // Both sides bump: invert direction
                    next_state = (state == WALK_LEFT) ? WALK_RIGHT : WALK_LEFT;
                end else if (bump_left) begin
                    // Bumped on left -> walk right
                    next_state = WALK_RIGHT;
                end else begin
                    // Bumped on right -> walk left
                    next_state = WALK_LEFT;
                end
                next_fall_timer = 5'd0;
            end else begin
                // Keep walking same direction
                next_state = state;
                next_fall_timer = 5'd0;
            end
        end else if (is_dig) begin
            if (!ground) begin
                // No ground, start falling same direction
                next_state = (state == DIG_LEFT) ? FALL_LEFT : FALL_RIGHT;
                next_fall_timer = 5'd1;
            end else begin
                // Keep digging
                next_state = state;
                next_fall_timer = 5'd0;
            end
        end else begin
            // Undefined states go to WALK_LEFT as default safe state
            next_state = WALK_LEFT;
            next_fall_timer = 5'd0;
        end
    end

    // Outputs are Moore type: depend only on state
    assign walk_left  = (state == WALK_LEFT);
    assign walk_right = (state == WALK_RIGHT);
    assign digging    = (state == DIG_LEFT) || (state == DIG_RIGHT);
    assign aaah       = (state == FALL_LEFT) || (state == FALL_RIGHT);

endmodule

state.tb_power:
`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
// Power testbench written by the JEV_RTL harness, in the style of the REvolution
// tb_pt templates: seed 32'hC0DE0042, 8 reset cycles, 16 warm-up cycles, 4000 measured
// cycles, a new random value on each data input in every cycle.
module tb_power_TopModule;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic aaah;
  logic areset;
  logic bump_left;
  logic bump_right;
  logic clk;
  logic dig;
  logic digging;
  logic ground;
  logic walk_left;
  logic walk_right;
  logic [31:0] _rnd;
  always #(CLK_HALF) clk = ~clk;
  TopModule dut (
    .aaah(aaah),
    .areset(areset),
    .bump_left(bump_left),
    .bump_right(bump_right),
    .clk(clk),
    .dig(dig),
    .digging(digging),
    .ground(ground),
    .walk_left(walk_left),
    .walk_right(walk_right)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    bump_left = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    bump_right = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    dig = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    ground = _rnd[0];
    areset = (($urandom % 32) == 0) ? 1'b1 : 1'b0;
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    clk = 1'b0;
    bump_left = '0;
    bump_right = '0;
    dig = '0;
    ground = '0;
    areset = 1'b1;
    repeat (RESET_CYCLES) @(negedge clk);
    areset = 1'b0;
    for (int _k = 0; _k < PT_WARMUP_CYCLES; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpfile("power.vcd");
    $dumpvars(0, tb_power_TopModule);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + PT_WARMUP_CYCLES + RESET_CYCLES + 200)); $display("tb_power_TopModule TIMEOUT"); $finish; end
endmodule
